import { z } from 'zod'

// Runtime values come from window._env_ (public/env.js, regenerated by
// scripts/entrypoint.sh when the container starts) and override build-time
// import.meta.env values.
export function createEnv<T extends z.ZodRawShape>(shape: T): Readonly<z.infer<z.ZodObject<T>>> {
  const schema = z.object(shape)

  const runtime = (globalThis as { _env_?: Record<string, string> })._env_ || {}
  const build = import.meta.env ?? {}

  const merged = { ...build, ...runtime }

  const parsed = schema.safeParse(merged)

  if (!parsed.success) {
    console.error('❌ Invalid environment variables')
    console.error(JSON.stringify(z.treeifyError(parsed.error), null, 2))
    throw new Error('Invalid environment configuration')
  }

  return Object.freeze(parsed.data)
}
